import React, { useEffect, useRef } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    const current = containerRef.current;
    if (!current) return;

    // Clear previous widget if it exists
    current.innerHTML = '';

    // Insert TradingView Ticker widget
    current.innerHTML = `
      <div class="tradingview-widget-container">
        <div class="tradingview-widget-container__widget"></div>
        <div class="tradingview-widget-copyright"><a href="https://www.tradingview.com/symbols/NIFTY/" rel="noopener" target="_blank"><span class="blue-text">NIFTY Index</span></a> by TradingView</div>
      </div>
    `;

    // Load the TradingView script
    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-single-quote.js';
    script.type = 'text/javascript';
    script.async = true;

    // Create the config as a separate script element
    const config = document.createElement('script');
    config.type = 'application/json';
    config.innerHTML = `{
      "symbol": "NSE:NIFTY",
      "width": "100%",
      "isTransparent": false,
      "colorTheme": "light",
      "locale": "en"
    }`;

    current.appendChild(config);
    current.appendChild(script);

    return () => {
      if (current) {
        current.innerHTML = '';
      }
    };
  }, []);

  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">India Market: NIFTY 50</h3>
      <div ref={containerRef} className="chart-embed"></div>
    </div>
  );
};

export default NiftyChart;
